"""Colab Diagnostic Tool: OOF Prediction vs Text Truncation Analysis for H2.

Scope: READ-ONLY statistical diagnosis on existing cached predictions and training data.
Can be executed directly on hosted Google Colab by Codex.
NO MODEL TRAINING OR FITTING IS PERFORMED IN THIS SCRIPT.
"""

import argparse
import json
import os
import re
import sys
from pathlib import Path
import numpy as np


def normalize_text(text):
    clean = re.sub(r'\s+', ' ', str(text).lower().strip())
    return f'^{clean}$'


def count_interleaved_tokens(text):
    """Count number of tokens generated by SubwordTokenizer (min_n=3, max_n=5)."""
    s = normalize_text(text)
    L = len(s)
    cnt = 0
    for i in range(L):
        for n in (3, 4, 5):
            if i + n <= L:
                cnt += 1
    return cnt


def compute_metrics(y_true, y_pred, n_classes=4):
    """Compute Macro F1, Accuracy, and per-class precision, recall, F1, and confusion matrix."""
    y_true = np.asarray(y_true, dtype=int)
    y_pred = np.asarray(y_pred, dtype=int)
    cm = np.zeros((n_classes, n_classes), dtype=int)
    for t, p in zip(y_true, y_pred):
        if 0 <= t < n_classes and 0 <= p < n_classes:
            cm[t, p] += 1

    per_class = {}
    f1_list = []
    for c in range(n_classes):
        tp = int(cm[c, c])
        fp = int(cm[:, c].sum() - tp)
        fn = int(cm[c, :].sum() - tp)
        support = int(cm[c, :].sum())
        prec = tp / max(tp + fp, 1)
        rec = tp / max(tp + fn, 1)
        f1 = (2.0 * prec * rec) / max(prec + rec, 1e-12)
        f1_list.append(f1)
        per_class[str(c)] = {
            'tp': tp,
            'fp': fp,
            'fn': fn,
            'support': support,
            'precision': float(round(prec, 6)),
            'recall': float(round(rec, 6)),
            'f1': float(round(f1, 6)),
        }

    macro_f1 = float(np.mean(f1_list))
    accuracy = float(np.trace(cm) / max(len(y_true), 1))
    return {
        'macro_f1': float(round(macro_f1, 6)),
        'accuracy': float(round(accuracy, 6)),
        'per_class': per_class,
        'confusion_matrix': cm.tolist(),
        'support_total': len(y_true)
    }


def run_diagnostic(train_comments, y_true, baseline_preds, candidate_preds, max_seq_len=256):
    """Core diagnostic logic matching predictions against truncation."""
    n_samples = len(train_comments)
    assert len(y_true) == n_samples
    assert len(baseline_preds) == n_samples
    assert len(candidate_preds) == n_samples

    # 1. Compute token counts and character lengths
    char_lens = np.array([len(normalize_text(t)) for t in train_comments], dtype=int)
    token_counts = np.array([count_interleaved_tokens(t) for t in train_comments], dtype=int)
    is_truncated = token_counts > max_seq_len

    trunc_mask = is_truncated
    nontrunc_mask = ~is_truncated

    # 2. Compute metrics on all subsets
    metrics_all_base = compute_metrics(y_true, baseline_preds)
    metrics_all_cand = compute_metrics(y_true, candidate_preds)

    metrics_trunc_base = compute_metrics(y_true[trunc_mask], baseline_preds[trunc_mask])
    metrics_trunc_cand = compute_metrics(y_true[trunc_mask], candidate_preds[trunc_mask])

    metrics_nontrunc_base = compute_metrics(y_true[nontrunc_mask], baseline_preds[nontrunc_mask])
    metrics_nontrunc_cand = compute_metrics(y_true[nontrunc_mask], candidate_preds[nontrunc_mask])

    # 3. Analyze Disagreements (flips)
    flips = baseline_preds != candidate_preds
    n_flips = int(flips.sum())

    good_flips = (baseline_preds != y_true) & (candidate_preds == y_true)
    bad_flips = (baseline_preds == y_true) & (candidate_preds != y_true)

    flips_trunc = flips & trunc_mask
    flips_nontrunc = flips & nontrunc_mask

    good_trunc = good_flips & trunc_mask
    good_nontrunc = good_flips & nontrunc_mask

    bad_trunc = bad_flips & trunc_mask
    bad_nontrunc = bad_flips & nontrunc_mask

    # Per-class truncation breakdown
    per_class_truncation = {}
    for c in range(4):
        c_mask = y_true == c
        c_total = int(c_mask.sum())
        c_trunc = int((c_mask & trunc_mask).sum())
        per_class_truncation[str(c)] = {
            'total_samples': c_total,
            'truncated_samples': c_trunc,
            'truncation_rate': float(round(c_trunc / max(c_total, 1), 4)),
            'mean_chars': float(round(float(char_lens[c_mask].mean()), 1)) if c_total > 0 else 0.0,
            'median_chars': float(round(float(np.median(char_lens[c_mask])), 1)) if c_total > 0 else 0.0,
        }

    # Disagreement details by true class
    flips_by_class = {}
    for c in range(4):
        c_mask = y_true == c
        flips_by_class[str(c)] = {
            'total_flips': int((c_mask & flips).sum()),
            'good_flips_total': int((c_mask & good_flips).sum()),
            'bad_flips_total': int((c_mask & bad_flips).sum()),
            'good_flips_in_truncated': int((c_mask & good_trunc).sum()),
            'bad_flips_in_truncated': int((c_mask & bad_trunc).sum()),
            'good_flips_in_nontruncated': int((c_mask & good_nontrunc).sum()),
            'bad_flips_in_nontruncated': int((c_mask & bad_nontrunc).sum()),
        }

    report = {
        'summary': {
            'total_samples': n_samples,
            'max_seq_len': max_seq_len,
            'approx_char_cutoff': 86,
            'truncated_samples': int(trunc_mask.sum()),
            'truncated_ratio': float(round(float(trunc_mask.mean()), 4)),
            'nontruncated_samples': int(nontrunc_mask.sum()),
            'total_flips': n_flips,
            'good_flips': int(good_flips.sum()),
            'bad_flips': int(bad_flips.sum()),
            'net_gain': int(good_flips.sum() - bad_flips.sum()),
        },
        'per_class_truncation': per_class_truncation,
        'flips_by_class': flips_by_class,
        'overall_comparison': {
            'baseline_macro_f1': metrics_all_base['macro_f1'],
            'candidate_macro_f1': metrics_all_cand['macro_f1'],
            'delta_macro_f1': float(round(metrics_all_cand['macro_f1'] - metrics_all_base['macro_f1'], 6)),
        },
        'truncated_subset_comparison': {
            'count': int(trunc_mask.sum()),
            'baseline_macro_f1': metrics_trunc_base['macro_f1'],
            'candidate_macro_f1': metrics_trunc_cand['macro_f1'],
            'delta_macro_f1': float(round(metrics_trunc_cand['macro_f1'] - metrics_trunc_base['macro_f1'], 6)),
            'baseline_per_class': metrics_trunc_base['per_class'],
            'candidate_per_class': metrics_trunc_cand['per_class'],
            'confusion_matrix_baseline': metrics_trunc_base['confusion_matrix'],
            'confusion_matrix_candidate': metrics_trunc_cand['confusion_matrix'],
        },
        'nontruncated_subset_comparison': {
            'count': int(nontrunc_mask.sum()),
            'baseline_macro_f1': metrics_nontrunc_base['macro_f1'],
            'candidate_macro_f1': metrics_nontrunc_cand['macro_f1'],
            'delta_macro_f1': float(round(metrics_nontrunc_cand['macro_f1'] - metrics_nontrunc_base['macro_f1'], 6)),
            'baseline_per_class': metrics_nontrunc_base['per_class'],
            'candidate_per_class': metrics_nontrunc_cand['per_class'],
            'confusion_matrix_baseline': metrics_nontrunc_base['confusion_matrix'],
            'confusion_matrix_candidate': metrics_nontrunc_cand['confusion_matrix'],
        },
    }
    return report


def main():
    p = argparse.ArgumentParser(description="Analyze H2 OOF prediction errors against text truncation.")
    p.add_argument('--train-csv', default=None, help='Path to ds102_train.csv')
    p.add_argument('--oof-npz', default=None, help='Path to outer_oof_focal.npz or dir containing it')
    p.add_argument('--export-json', default='h2_truncation_analysis.json', help='Output JSON report path')
    args = p.parse_args()

    # 1. Locate train CSV
    train_path = None
    candidates_csv = [
        args.train_csv,
        Path('/content/ds102_v53/source/data/ds102_train.csv'),
        Path('/content/ds102_data/ds102_train.csv'),
        Path('data/ds102_train.csv'),
        Path('/Users/ngien2306/Downloads/ds-102-r-11-cnvn/ds102_train.csv'),
    ]
    for c in candidates_csv:
        if c and Path(c).is_file():
            train_path = Path(c)
            break

    if not train_path:
        print("ERROR: Cannot find ds102_train.csv. Specify --train-csv.", file=sys.stderr)
        sys.exit(1)

    print(f"Loading training data from: {train_path}")
    import pandas as pd
    df = pd.read_csv(train_path, keep_default_na=False)
    comments = df['comment'].fillna('').astype(str).tolist()
    y_true = df['spam_label'].to_numpy(dtype=int)

    # 2. Locate OOF NPZ
    oof_path = None
    candidates_npz = [
        args.oof_npz,
        Path('/content/output_h2_checked/outer_oof_focal.npz'),
        Path('output_h2_checked/outer_oof_focal.npz'),
        Path('/content/outer_oof_focal.npz'),
    ]
    for c in candidates_npz:
        if c:
            cp = Path(c)
            if cp.is_file():
                oof_path = cp
                break
            if cp.is_dir() and (cp / 'outer_oof_focal.npz').is_file():
                oof_path = cp / 'outer_oof_focal.npz'
                break

    if not oof_path:
        print("ERROR: Cannot find outer_oof_focal.npz. Specify --oof-npz.", file=sys.stderr)
        sys.exit(1)

    print(f"Loading OOF predictions from: {oof_path}")
    z = np.load(oof_path)
    base_pred = z['baseline']
    cand_pred = z['candidate']

    print("Running truncation cross-tabulation diagnostic...")
    report = run_diagnostic(comments, y_true, base_pred, cand_pred, max_seq_len=256)

    out_p = Path(args.export_json)
    out_p.write_text(json.dumps(report, indent=2, ensure_ascii=False))
    print(f"Report written successfully to: {out_p.resolve()}")

    # Print summary highlights
    s = report['summary']
    print("\n" + "=" * 60)
    print("H2 TRUNCATION DIAGNOSTIC SUMMARY")
    print("=" * 60)
    print(f"Total reviews:        {s['total_samples']}")
    print(f"Truncated (>256 tok): {s['truncated_samples']} ({s['truncated_ratio']*100:.1f}%)")
    print(f"Non-truncated:        {s['nontruncated_samples']} ({(1 - s['truncated_ratio'])*100:.1f}%)")
    print("-" * 60)
    ov = report['overall_comparison']
    print(f"Overall Macro F1:     Base={ov['baseline_macro_f1']:.5f} -> Cand={ov['candidate_macro_f1']:.5f} (Delta={ov['delta_macro_f1']:+.5f})")
    tr = report['truncated_subset_comparison']
    print(f"Truncated Macro F1:   Base={tr['baseline_macro_f1']:.5f} -> Cand={tr['candidate_macro_f1']:.5f} (Delta={tr['delta_macro_f1']:+.5f})")
    nt = report['nontruncated_subset_comparison']
    print(f"Non-truncated Macro:  Base={nt['baseline_macro_f1']:.5f} -> Cand={nt['candidate_macro_f1']:.5f} (Delta={nt['delta_macro_f1']:+.5f})")
    print("=" * 60)


if __name__ == '__main__':
    main()
